"""Dependency ordering for registered runtime engines."""

from __future__ import annotations

from collections import deque

from .registry import EngineRegistry


class DependencyCycleError(RuntimeError):
    """Raised when engine dependencies contain a cycle."""


class DependencyGraph:
    """Validate dependencies and calculate execution order."""

    def __init__(self, registry: EngineRegistry) -> None:
        self._registry = registry

    def execution_order(
        self,
        engine_names: tuple[str, ...] | None = None,
    ) -> tuple[str, ...]:
        """Return engines in dependency-safe execution order."""

        self._registry.validate_dependencies()

        requested = self._resolve_requested(engine_names)
        nodes = self._expand_dependencies(requested)

        indegree = {name: 0 for name in nodes}
        dependents = {name: [] for name in nodes}

        for name in nodes:
            registration = self._registry.require(name)

            for dependency in registration.dependencies:
                if dependency not in nodes:
                    continue

                indegree[name] += 1
                dependents[dependency].append(name)

        ready = deque(
            name
            for name in self._registry.names(include_disabled=False)
            if name in nodes and indegree[name] == 0
        )

        ordered: list[str] = []

        while ready:
            current = ready.popleft()
            ordered.append(current)

            for dependent in dependents[current]:
                indegree[dependent] -= 1

                if indegree[dependent] == 0:
                    ready.append(dependent)

        if len(ordered) != len(nodes):
            unresolved = tuple(
                name for name in nodes if indegree[name] > 0
            )

            raise DependencyCycleError(
                "Circular engine dependency detected: "
                + " -> ".join(unresolved)
            )

        return tuple(ordered)

    def dependencies_of(self, engine_name: str) -> tuple[str, ...]:
        """Return an engine's direct dependencies."""

        return self._registry.require(engine_name).dependencies

    def transitive_dependencies_of(
        self,
        engine_name: str,
    ) -> tuple[str, ...]:
        """Return all dependencies in execution order."""

        registration = self._registry.require(engine_name)
        order = self.execution_order((registration.name,))

        return tuple(
            name for name in order if name != registration.name
        )

    def _resolve_requested(
        self,
        engine_names: tuple[str, ...] | None,
    ) -> tuple[str, ...]:
        if engine_names is None:
            return self._registry.names(include_disabled=False)

        requested: list[str] = []

        for engine_name in engine_names:
            registration = self._registry.require(engine_name)

            if not registration.enabled:
                raise RuntimeError(
                    f"Requested engine is disabled: {registration.name}"
                )

            if registration.name not in requested:
                requested.append(registration.name)

        return tuple(requested)

    def _expand_dependencies(
        self,
        requested: tuple[str, ...],
    ) -> set[str]:
        expanded: set[str] = set()
        pending = list(requested)

        while pending:
            current = pending.pop()

            if current in expanded:
                continue

            registration = self._registry.require(current)
            expanded.add(current)
            pending.extend(registration.dependencies)

        return expanded

from __future__ import annotations

import unittest

from src.runtime import Engine, EngineRegistry, PlatformContext
from src.runtime.dependency_graph import (
    DependencyCycleError,
    DependencyGraph,
)


class WalletEngine(Engine):
    name = "wallet"

    def execute(self, context: PlatformContext) -> None:
        return None


class ConsensusEngine(Engine):
    name = "consensus"
    dependencies = ("wallet",)

    def execute(self, context: PlatformContext) -> None:
        return None


class SignalEngine(Engine):
    name = "signal"
    dependencies = ("consensus",)

    def execute(self, context: PlatformContext) -> None:
        return None


class ReportEngine(Engine):
    name = "report"
    dependencies = ("signal", "wallet")

    def execute(self, context: PlatformContext) -> None:
        return None


class CycleAEngine(Engine):
    name = "cycle_a"
    dependencies = ("cycle_b",)

    def execute(self, context: PlatformContext) -> None:
        return None


class CycleBEngine(Engine):
    name = "cycle_b"
    dependencies = ("cycle_a",)

    def execute(self, context: PlatformContext) -> None:
        return None


class DependencyGraphTests(unittest.TestCase):
    def setUp(self) -> None:
        self.registry = EngineRegistry()
        self.registry.register(WalletEngine())
        self.registry.register(ConsensusEngine())
        self.registry.register(SignalEngine())
        self.registry.register(ReportEngine())
        self.graph = DependencyGraph(self.registry)

    def test_full_execution_order(self) -> None:
        self.assertEqual(
            self.graph.execution_order(),
            ("wallet", "consensus", "signal", "report"),
        )

    def test_requested_engine_includes_dependencies(self) -> None:
        self.assertEqual(
            self.graph.execution_order(("report",)),
            ("wallet", "consensus", "signal", "report"),
        )

    def test_direct_dependencies(self) -> None:
        self.assertEqual(
            self.graph.dependencies_of("report"),
            ("signal", "wallet"),
        )

    def test_transitive_dependencies(self) -> None:
        self.assertEqual(
            self.graph.transitive_dependencies_of("report"),
            ("wallet", "consensus", "signal"),
        )

    def test_cycle_is_detected(self) -> None:
        registry = EngineRegistry()
        registry.register(CycleAEngine())
        registry.register(CycleBEngine())

        with self.assertRaises(DependencyCycleError):
            DependencyGraph(registry).execution_order()


if __name__ == "__main__":
    unittest.main()
